def List_Servers(status=None, project_id=None, location=None, auth_mode=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0016000" if __import__("os").path.isdir("./environment_mix/0016000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "List Servers"

    def _parse_iso(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            if ts.endswith("Z"):
                return datetime.datetime.fromisoformat(ts[:-1])
            return datetime.datetime.fromisoformat(ts)
        except Exception:
            return None

    # ---- observable dynamics: request logs + rate limit (if collection exists) ----
    log_fname = None
    for cand in ("request_logs.json", "usage.json", "audit_logs.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            log_fname = cand
            break

    logs = _load(log_fname) if log_fname else None
    if log_fname and not isinstance(logs, list):
        logs = []

    # simple per-endpoint rate limiting using logs, only if logs exist
    if log_fname:
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        recent = 0
        kept = []
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_iso(r.get("timestamp") or r.get("created_at"))
            if ts is None or ts >= cutoff:
                kept.append(r)
                if r.get("endpoint") == endpoint:
                    recent += 1
        logs = kept
        if recent >= 240:
            logs.append({
                "id": f"rq_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": "RATE_LIMIT",
                "credential_id": None,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now_iso
            })
            _save(log_fname, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded.")

    def _decode_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or cur == "":
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            off = obj.get("offset")
            if not isinstance(off, int) or off < 0:
                return None
            return off
        except Exception:
            return None

    def _encode_cursor(off):
        payload = json.dumps({"offset": off}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # ---- validate inputs ----
    allowed_status = {"active", "disabled", "deleted"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        if log_fname:
            logs.append({
                "id": f"rq_{int(time.time()*1000)}",
                "endpoint": endpoint,
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "credential_id": None,
                "latency_ms": int((time.time() - t0) * 1000),
                "timestamp": now_iso
            })
            _save(log_fname, logs)
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status", allowed=sorted(allowed_status))

    if project_id is not None and not isinstance(project_id, str):
        if log_fname:
            logs.append({"id": f"rq_{int(time.time()*1000)}", "endpoint": endpoint, "status": "error", "error_code": "VALIDATION_ERROR",
                         "credential_id": None, "latency_ms": int((time.time() - t0) * 1000), "timestamp": now_iso})
            _save(log_fname, logs)
        return _err("VALIDATION_ERROR", "project_id must be a string.", field="project_id")
    if location is not None and not isinstance(location, str):
        if log_fname:
            logs.append({"id": f"rq_{int(time.time()*1000)}", "endpoint": endpoint, "status": "error", "error_code": "VALIDATION_ERROR",
                         "credential_id": None, "latency_ms": int((time.time() - t0) * 1000), "timestamp": now_iso})
            _save(log_fname, logs)
        return _err("VALIDATION_ERROR", "location must be a string.", field="location")

    # Tool enum differs from datastore schema; accept tool enum and map to schema values
    # tool: service_account|oauth_user|oidc ; schema: service_account_json|oauth_user|adc
    # Map: service_account -> service_account_json ; oauth_user -> oauth_user ; oidc -> adc (closest supported)
    auth_map = {"service_account": "service_account_json", "oauth_user": "oauth_user", "oidc": "adc"}
    allowed_auth = set(auth_map.keys())
    auth_mode_schema = None
    if auth_mode is not None:
        if not isinstance(auth_mode, str) or auth_mode not in allowed_auth:
            if log_fname:
                logs.append({"id": f"rq_{int(time.time()*1000)}", "endpoint": endpoint, "status": "error", "error_code": "VALIDATION_ERROR",
                             "credential_id": None, "latency_ms": int((time.time() - t0) * 1000), "timestamp": now_iso})
                _save(log_fname, logs)
            return _err("VALIDATION_ERROR", "Invalid auth_mode filter.", field="auth_mode", allowed=sorted(allowed_auth))
        auth_mode_schema = auth_map[auth_mode]

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        if log_fname:
            logs.append({"id": f"rq_{int(time.time()*1000)}", "endpoint": endpoint, "status": "error", "error_code": "VALIDATION_ERROR",
                         "credential_id": None, "latency_ms": int((time.time() - t0) * 1000), "timestamp": now_iso})
            _save(log_fname, logs)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    off = _decode_cursor(cursor)
    if off is None:
        if log_fname:
            logs.append({"id": f"rq_{int(time.time()*1000)}", "endpoint": endpoint, "status": "error", "error_code": "VALIDATION_ERROR",
                         "credential_id": None, "latency_ms": int((time.time() - t0) * 1000), "timestamp": now_iso})
            _save(log_fname, logs)
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # ---- ambient auth: choose a principal context that exists (do not refuse well-formed calls) ----
    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    principal = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active":
            principal = u
            break
    if principal is None:
        for u in users:
            if isinstance(u, dict) and u.get("status") in ("active", "suspended"):
                principal = u
                break
    # If no users exist, proceed as unauthenticated viewer with no restrictions beyond global visibility.
    # This API's "visible servers" isn't backed by an ACL table in schema; treat as all servers visible.

    servers = _load("servers.json")
    if not isinstance(servers, list):
        servers = []

    # ---- filter ----
    out = []
    for s in servers:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        if project_id is not None and s.get("project_id") != project_id:
            continue
        if location is not None and s.get("location") != location:
            continue
        if auth_mode_schema is not None and s.get("auth_mode") != auth_mode_schema:
            continue
        out.append(s)

    # sort stable by created_at then id
    def _sort_key(r):
        dt = _parse_iso(r.get("created_at"))
        return (dt or datetime.datetime.min, r.get("id") or "")
    out.sort(key=_sort_key)

    total = len(out)
    page = out[off:off + limit]
    next_off = off + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    resp = {
        "servers": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor
    }

    if log_fname:
        logs.append({
            "id": f"rq_{int(time.time()*1000)}",
            "endpoint": endpoint,
            "status": "ok",
            "credential_id": principal.get("id") if isinstance(principal, dict) else None,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso
        })
        _save(log_fname, logs)

    return resp

def Create_Server(display_name=None, project_id=None, location=None, auth_mode=None, service_account_email=None, secret_ref=None, scopes=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0016000" if __import__("os").path.isdir("./environment_mix/0016000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "Create Server"

    # ---- observable dynamics: request logs + rate limit (if collection exists) ----
    log_fname = None
    for cand in ("request_logs.json", "usage.json", "audit_logs.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            log_fname = cand
            break
    logs = _load(log_fname) if log_fname else None
    if log_fname and not isinstance(logs, list):
        logs = []

    def _log(status, error_code=None, credential_id=None, detail=None):
        if not log_fname:
            return
        row = {
            "id": f"rq_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "status": status,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso
        }
        if error_code:
            row["error_code"] = error_code
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save(log_fname, logs)

    def _rate_limit_check():
        if not log_fname:
            return None
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        kept = []
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if isinstance(ts, str) and ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
            except Exception:
                dt = None
            if dt is None or dt >= cutoff:
                kept.append(r)
                if r.get("endpoint") == endpoint:
                    recent += 1
        logs[:] = kept
        if recent >= 60:
            _log("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded.")
        return None

    rl = _rate_limit_check()
    if rl:
        return rl

    # ---- ambient auth: need an active owner/admin ----
    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    principal = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active" and u.get("role") in ("owner", "admin"):
            principal = u
            break
    if principal is None:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Requires an active user with role owner or admin.")

    # ---- validate required fields (allow missing to return structured error, not raise) ----
    if not isinstance(display_name, str) or not (1 <= len(display_name) <= 200):
        _log("error", "VALIDATION_ERROR", principal.get("id") if principal else None, "validation:display_name")
        return _err("VALIDATION_ERROR", "display_name must be a non-empty string up to 200 characters.", field="display_name")
    if not isinstance(project_id, str) or len(project_id) < 1:
        _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:project_id")
        return _err("VALIDATION_ERROR", "project_id must be a non-empty string.", field="project_id")
    if not isinstance(location, str) or len(location) < 1:
        _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:location")
        return _err("VALIDATION_ERROR", "location must be a non-empty string.", field="location")
    if not isinstance(auth_mode, str):
        _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:auth_mode")
        return _err("VALIDATION_ERROR", "auth_mode must be a string.", field="auth_mode")

    # tool auth enum -> schema enum
    auth_map = {"service_account": "service_account_json", "oauth_user": "oauth_user", "oidc": "adc"}
    if auth_mode not in auth_map:
        _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:auth_mode_enum")
        return _err("VALIDATION_ERROR", "Invalid auth_mode.", field="auth_mode", allowed=sorted(auth_map.keys()))
    auth_mode_schema = auth_map[auth_mode]

    if scopes is not None and not isinstance(scopes, list):
        _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:scopes")
        return _err("VALIDATION_ERROR", "scopes must be an array of strings.", field="scopes")
    if isinstance(scopes, list) and any(not isinstance(x, str) or x == "" for x in scopes):
        _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:scopes_items")
        return _err("VALIDATION_ERROR", "scopes must contain only non-empty strings.", field="scopes")

    # No raw secrets: validate secret_ref and service_account_email are pointers/ids, not key material
    def _contains_raw_secret(s):
        if not isinstance(s, str):
            return False
        low = s.lower()
        if "-----begin" in low or "private_key" in low or "-----end" in low:
            return True
        t = s.strip()
        if (t.startswith("{") and t.endswith("}")) or (t.startswith("[") and t.endswith("]")):
            # likely JSON blob, not a ref
            return True
        if low.startswith("ya29.") or "bearer " in low:
            return True
        return False

    if secret_ref is not None:
        if not isinstance(secret_ref, str) or secret_ref.strip() == "":
            _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:secret_ref")
            return _err("VALIDATION_ERROR", "secret_ref must be a non-empty string reference.", field="secret_ref")
        if _contains_raw_secret(secret_ref):
            _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:secret_ref_raw")
            return _err("VALIDATION_ERROR", "Raw secrets are not allowed; secret_ref must be an external reference pointer.", field="secret_ref")

    if service_account_email is not None:
        if not isinstance(service_account_email, str) or service_account_email.strip() == "":
            _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:service_account_email")
            return _err("VALIDATION_ERROR", "service_account_email must be a non-empty string.", field="service_account_email")
        if _contains_raw_secret(service_account_email):
            _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:service_account_email_raw")
            return _err("VALIDATION_ERROR", "service_account_email must be an email, not credential material.", field="service_account_email")

    # Enforce auth_mode-specific constraints (per schema)
    if auth_mode_schema == "service_account_json":
        if service_account_email is None or secret_ref is None:
            _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:sa_requires_email_ref")
            return _err("VALIDATION_ERROR", "auth_mode=service_account requires service_account_email and secret_ref (no JSON material allowed).")
    if auth_mode_schema == "oauth_user":
        if not isinstance(scopes, list) or len(scopes) == 0:
            _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:oauth_requires_scopes")
            return _err("VALIDATION_ERROR", "auth_mode=oauth_user requires a non-empty scopes list.", field="scopes")

    # ---- unique(display_name) among non-deleted? constraint says unique(display_name) globally ----
    servers = _load("servers.json")
    if not isinstance(servers, list):
        servers = []
    for s in servers:
        if isinstance(s, dict) and s.get("display_name") == display_name:
            _log("error", "CONFLICT", principal.get("id"), "conflict:display_name")
            return _err("CONFLICT", "display_name must be unique.", field="display_name")

    # ---- create id (match existing convention) ----
    # We can't generate ULID without deps; produce high-entropy uppercase token with prefix and length >= 18
    new_id = "bq_srv_" + secrets.token_hex(12).upper()  # 24 hex chars
    existing_ids = {s.get("id") for s in servers if isinstance(s, dict)}
    while new_id in existing_ids:
        new_id = "bq_srv_" + secrets.token_hex(12).upper()

    row = {
        "id": new_id,
        "display_name": display_name,
        "project_id": project_id,
        "location": location,
        "auth_mode": auth_mode_schema,
        "service_account_email": service_account_email if auth_mode_schema == "service_account_json" else None,
        "secret_ref": secret_ref if auth_mode_schema == "service_account_json" else (secret_ref if secret_ref is not None else None),
        "scopes": scopes if isinstance(scopes, list) else [],
        "status": "active",
        "created_at": now_iso,
        "updated_at": now_iso
    }

    servers.append(row)
    _save("servers.json", servers)

    _log("ok", None, principal.get("id"))
    return {"server": row}

