            return _err("VALIDATION_ERROR", "service_account_email must be an email, not credential material.", field="service_account_email")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled", "deleted"):
            _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:status")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "disabled", "deleted"])

    # Must provide at least one mutable field or status transition
    if all(v is None for v in (display_name, project_id, location, auth_mode, service_account_email, secret_ref, scopes, status)):
        _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:no_fields")
        return _err("VALIDATION_ERROR", "No fields to update.")

    # ---- load server and enforce unique(display_name) ----
    servers = _load("servers.json")
    if not isinstance(servers, list):
        servers = []

    idx = None
    server = None
    for i, s in enumerate(servers):
        if isinstance(s, dict) and s.get("id") == id:
            idx = i
            server = s
            break
    if server is None:
        _log("error", "NOT_FOUND", principal.get("id"))
        return _err("NOT_FOUND", "Server not found.", field="id")

    if display_name is not None and display_name != server.get("display_name"):
        for s in servers:
            if isinstance(s, dict) and s.get("display_name") == display_name and s.get("id") != id:
                _log("error", "CONFLICT", principal.get("id"), "conflict:display_name")
                return _err("CONFLICT", "display_name must be unique.", field="display_name")

    # ---- lifecycle transition enforcement ----
    transitions = {
        "active": {"disabled", "deleted"},
        "disabled": {"active", "deleted"},
        "deleted": set()
    }
    if status is not None:
        cur = server.get("status")
        if cur not in transitions:
            _log("error", "CONFLICT", principal.get("id"), "conflict:bad_current_status")
            return _err("CONFLICT", "Server is in an invalid lifecycle state.")
        if status != cur and status not in transitions[cur]:
            _log("error", "INVALID_TRANSITION", principal.get("id"), "transition:invalid")
            return _err("INVALID_TRANSITION", f"Invalid status transition from {cur} to {status}.", from_status=cur, to_status=status)

    # ---- apply updates (compute final auth_mode to validate constraints) ----
    new_server = dict(server)

    if display_name is not None:
        new_server["display_name"] = display_name
    if project_id is not None:
        new_server["project_id"] = project_id
    if location is not None:
        new_server["location"] = location
    if scopes is not None:
        new_server["scopes"] = scopes

    if auth_mode_schema is not None:
        new_server["auth_mode"] = auth_mode_schema
    if service_account_email is not None:
        new_server["service_account_email"] = service_account_email
    if secret_ref is not None:
        new_server["secret_ref"] = secret_ref
    if status is not None:
        new_server["status"] = status

    # enforce schema-like constraints after update
    if not isinstance(new_server.get("project_id"), str) or new_server.get("project_id") == "":
        _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:project_id_post")
        return _err("VALIDATION_ERROR", "project_id must be non-empty.")
    if new_server.get("auth_mode") == "service_account_json":
        if not new_server.get("service_account_email") or not new_server.get("secret_ref"):
            _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:sa_requires_email_ref_post")
            return _err("VALIDATION_ERROR", "auth_mode=service_account requires service_account_email and secret_ref.")
    if new_server.get("auth_mode") == "oauth_user":
        sc = new_server.get("scopes")
        if not isinstance(sc, list) or len(sc) == 0:
            _log("error", "VALIDATION_ERROR", principal.get("id"), "validation:oauth_requires_scopes_post")
            return _err("VALIDATION_ERROR", "auth_mode=oauth_user requires a non-empty scopes list.", field="scopes")

    # ---- persist server update ----
    new_server["updated_at"] = now_iso
    servers[idx] = new_server
    _save("servers.json", servers)

    # ---- business rule: disabling/deleting server revokes active sessions scoped to it ----
    if status in ("disabled", "deleted") and status != server.get("status"):
        auth_sessions = _load("auth_sessions.json")
        if not isinstance(auth_sessions, list):
            auth_sessions = []
        changed = False
        for s in auth_sessions:
            if not isinstance(s, dict):
                continue
            if s.get("server_id") == id and s.get("status") == "active":
                # valid transition active -> revoked
                s["status"] = "revoked"
                s["updated_at"] = now_iso
                changed = True
        if changed:
            _save("auth_sessions.json", auth_sessions)

    _log("ok", None, principal.get("id"))
    return {"server": new_server}

def Create_API_Key(user_id, server_id, name, expires_at=None, **_extra):
    import json, os, datetime, time, secrets, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0016000" if __import__("os").path.isdir("./environment_mix/0016000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat().replace("+00:00", "Z")

    request_logs = _load("request_logs.json")
    if not isinstance(request_logs, list):
        request_logs = []
    def _log(status, credential_id=None, detail=None):
        latency_ms = int((time.time() - _t0) * 1000)
        row = {
            "id": "bq_rlg_" + secrets.token_hex(9).upper(),
            "endpoint": "Create API Key",
            "credential_id": credential_id,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now_iso
        }
        if detail is not None:
            row["detail"] = detail
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return "TYPE_ERROR"
        try:
            # Accept Z or offset; store normalized ISO Z
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    return "NAIVE"
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except ValueError:
            return "FORMAT_ERROR"

    # ---- Validate inputs (before auth/side effects except request log at end) ----
    if not isinstance(user_id, str) or re.match(r"^bq_usr_[0-9A-Z]{18,}$", user_id) is None:
        _log("error", detail="validation:user_id")
        return _err("VALIDATION_ERROR", "Invalid user_id.", field="user_id")
    if not isinstance(server_id, str) or re.match(r"^bq_srv_[0-9A-Z]{18,}$", server_id) is None:
        _log("error", detail="validation:server_id")
        return _err("VALIDATION_ERROR", "Invalid server_id.", field="server_id")
    if not isinstance(name, str) or len(name) < 1 or len(name) > 200:
        _log("error", detail="validation:name")
        return _err("VALIDATION_ERROR", "Invalid name.", field="name")

    exp_dt = None
    if expires_at is not None:
        exp_dt = _parse_dt(expires_at)
        if exp_dt == "TYPE_ERROR":
            _log("error", detail="validation:expires_at_type")
            return _err("VALIDATION_ERROR", "expires_at must be a string date-time.", field="expires_at")
        if exp_dt in ("FORMAT_ERROR", "NAIVE"):
            _log("error", detail="validation:expires_at_format")
            return _err("VALIDATION_ERROR", "expires_at must be an RFC3339/ISO-8601 date-time with timezone.", field="expires_at")
        if exp_dt <= now:
            _log("error", detail="validation:expires_at_past")
            return _err("VALIDATION_ERROR", "expires_at must be in the future.", field="expires_at")

    # ---- Load datastore ----
    users = _load("users.json")
    servers = _load("servers.json")
    api_keys = _load("api_keys.json")
    auth_sessions = _load("auth_sessions.json")

    if not isinstance(users, list) or not isinstance(servers, list) or not isinstance(api_keys, list) or not isinstance(auth_sessions, list):
        _log("error", detail="datastore:corrupt")
        return _err("CONFLICT", "Datastore is in an invalid state.")

    # ---- Enforce quotas/rate limits if present in settings (best-effort) ----
    settings = _load("settings.json")
    if not isinstance(settings, list):
        settings = []
    # global settings key (convention): rate_limits.create_api_key_per_minute / quotas.create_api_key_per_day
    def _active_setting(scope_type, key, user_id=None, server_id=None):
        for row in settings:
            if not isinstance(row, dict):
                continue
            if row.get("status") != "active":
                continue
            if row.get("scope_type") != scope_type:
                continue
            if row.get("key") != key:
                continue
            if scope_type == "global":
                if row.get("server_id") is None and row.get("user_id") is None:
                    return row
            elif scope_type == "user":
                if row.get("user_id") == user_id and row.get("server_id") is None:
                    return row
            elif scope_type == "server":
                if row.get("server_id") == server_id and row.get("user_id") is None:
                    return row
        return None

    def _get_int_from_setting(row, default=None):
        if not row:
            return default
        v = row.get("value")
        if isinstance(v, dict):
            # allow {"limit": N} or {"value": N}
            for k in ("limit", "value", "max"):
                if k in v and isinstance(v[k], int):
                    return v[k]
        if isinstance(v, int):
            return v
        return default

    per_min = _get_int_from_setting(_active_setting("global", "rate_limits.create_api_key_per_minute"), None)
    per_day = _get_int_from_setting(_active_setting("global", "quotas.create_api_key_per_day"), None)
    # Enforce using request logs if available. If logs missing, cannot enforce.
    if isinstance(per_min, int) and per_min >= 0:
        cutoff = now - datetime.timedelta(minutes=1)
        recent = 0
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "Create API Key":
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                if ts.endswith("Z"):
                    rdt = datetime.datetime.fromisoformat(ts[:-1]).replace(tzinfo=datetime.timezone.utc)
                else:
                    rdt = datetime.datetime.fromisoformat(ts)
                    if rdt.tzinfo is None:
                        continue
                    rdt = rdt.astimezone(datetime.timezone.utc)
            except ValueError:
                continue
            if rdt >= cutoff and r.get("status") == "success":
                recent += 1
        if recent >= per_min:
            _log("error", detail="rate_limit:per_minute")
            return _err("RATE_LIMIT", "Rate limit exceeded for Create API Key.")

    if isinstance(per_day, int) and per_day >= 0:
        cutoff = now - datetime.timedelta(days=1)
        recent = 0
        for r in request_logs:
            if not isinstance(r, dict):
                continue
            if r.get("endpoint") != "Create API Key":
                continue
            ts = r.get("timestamp")
            if not isinstance(ts, str):
                continue
            try:
                if ts.endswith("Z"):
                    rdt = datetime.datetime.fromisoformat(ts[:-1]).replace(tzinfo=datetime.timezone.utc)
                else:
                    rdt = datetime.datetime.fromisoformat(ts)
                    if rdt.tzinfo is None:
                        continue
                    rdt = rdt.astimezone(datetime.timezone.utc)
            except ValueError:
                continue
            if rdt >= cutoff and r.get("status") == "success":
                recent += 1
        if recent >= per_day:
            _log("error", detail="quota:per_day")
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded for Create API Key.")

    # ---- Resolve authenticated principal (ambient) and authorization ----
    # Since no credential parameter exists, pick any active, unexpired session whose user has owner/admin.
    # Prefer a session scoped to the requested server_id; otherwise a global session.
    def _dt_from_iso(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                return None
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    user_by_id = {u.get("id"): u for u in users if isinstance(u, dict) and isinstance(u.get("id"), str)}
    server_by_id = {s.get("id"): s for s in servers if isinstance(s, dict) and isinstance(s.get("id"), str)}

    target_user = user_by_id.get(user_id)
    if not target_user:
        _log("error", detail="not_found:user")
        return _err("NOT_FOUND", "User not found.", resource="users", id=user_id)
    if target_user.get("status") != "active":
        _log("error", detail="validation:user_inactive")
        return _err("VALIDATION_ERROR", "Target user must be active to create an API key.", field="user_id")

    target_server = server_by_id.get(server_id)
    if not target_server:
        _log("error", detail="not_found:server")
        return _err("NOT_FOUND", "Server not found.", resource="servers", id=server_id)
    if target_server.get("status") != "active":
        _log("error", detail="validation:server_inactive")
        return _err("VALIDATION_ERROR", "Target server must be active to create an API key.", field="server_id")

    # Find an authorized caller: active session + active user role owner/admin.
    authorized_session = None
    for sess in auth_sessions:
        if not isinstance(sess, dict):
            continue
        if sess.get("status") != "active":
            continue
        exp = _dt_from_iso(sess.get("expires_at"))
        if exp is None or exp <= now:
            continue
        sid = sess.get("server_id")
        if sid is not None and sid != server_id:
            continue
        caller = user_by_id.get(sess.get("user_id"))
        if not caller or caller.get("status") != "active":
            continue
        if caller.get("role") not in ("owner", "admin"):
            continue
        authorized_session = sess
        if sid == server_id:
            break
    if authorized_session is None:
        _log("error", detail="unauthorized:no_admin_session")
        return _err("UNAUTHORIZED", "No authorized session found to create API keys (requires owner/admin).")

    # ---- Enforce unique(user_id, name) ----
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("user_id") == user_id and k.get("name") == name:
            _log("error", detail="conflict:unique_user_name")
            return _err("CONFLICT", "An API key with this name already exists for the user.", field="name")

    # ---- Generate and store key (only once returned) ----
    raw_key = "bqk_" + secrets.token_urlsafe(32)
    key_prefix = raw_key[:8]
    key_hash = hashlib.sha256(raw_key.encode("utf-8")).hexdigest()

    # Enforce unique(key_hash)
    for k in api_keys:
        if isinstance(k, dict) and k.get("key_hash") == key_hash:
            # Extremely unlikely; regenerate once
            raw_key = "bqk_" + secrets.token_urlsafe(32)
            key_prefix = raw_key[:8]
            key_hash = hashlib.sha256(raw_key.encode("utf-8")).hexdigest()
            break
    for k in api_keys:
        if isinstance(k, dict) and k.get("key_hash") == key_hash:
            _log("error", detail="conflict:key_hash_collision")
            return _err("CONFLICT", "Could not generate a unique API key. Please retry.")

    # Determine initial status based on expires_at
    status = "active"
    exp_iso = None
    if exp_dt is not None:
        exp_iso = exp_dt.isoformat().replace("+00:00", "Z")
        if exp_dt <= now:
            status = "expired"

    # id convention: bq_key_ + 18+ uppercase hex
    new_id = "bq_key_" + secrets.token_hex(9).upper()

    row = {
        "id": new_id,
        "user_id": user_id,
        "server_id": server_id,
        "name": name,
        "key_prefix": key_prefix,
        "key_hash": key_hash,
        "last_used_at": None,
        "expires_at": exp_iso,
        "status": status,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    api_keys.append(row)
    _save("api_keys.json", api_keys)

    # Update caller last_login_at? (not required). Update session updated_at? (optional, but keep minimal).
    # Log and return including raw key only once.
    _log("success", credential_id=authorized_session.get("id"))
    return {
        "api_key": {
            "id": row["id"],
            "user_id": row["user_id"],
            "server_id": row["server_id"],
            "name": row["name"],
            "key_prefix": row["key_prefix"],
            "expires_at": row["expires_at"],
            "status": row["status"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"]
        },
        "key": raw_key
    }

def Revoke_API_Key(id=None, **_extra):
    import json, os, datetime, time, secrets, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0016000" if __import__("os").path.isdir("./environment_mix/0016000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_iso = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    endpoint = "Revoke API Key"

    # request log if exists
    log_fname = None
    for cand in ("request_logs.json", "usage.json", "audit_logs.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            log_fname = cand
            break
    logs = _load(log_fname) if log_fname else None
    if log_fname and not isinstance(logs, list):
        logs = []

    def _log(status_s, error_code=None, credential_id=None, detail=None):
        if not log_fname:
            return
        row = {
            "id": f"rq_{int(time.time()*1000)}_{secrets.token_hex(4)}",
            "endpoint": endpoint,
            "status": status_s,
            "credential_id": credential_id,
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": now_iso
        }
        if error_code:
            row["error_code"] = error_code
        if detail is not None:
            row["detail"] = detail
        logs.append(row)
        _save(log_fname, logs)

    # rate limit if logs exist
    if log_fname:
        cutoff = datetime.datetime.utcnow().replace(microsecond=0) - datetime.timedelta(seconds=60)
        kept, recent = [], 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = r.get("timestamp") or r.get("created_at")
            try:
                dt = datetime.datetime.fromisoformat(ts[:-1]) if isinstance(ts, str) and ts.endswith("Z") else datetime.datetime.fromisoformat(ts)
            except Exception:
                dt = None
            if dt is None or dt >= cutoff:
                kept.append(r)
                if r.get("endpoint") == endpoint:
                    recent += 1
        logs[:] = kept
        if recent >= 180:
            _log("error", "RATE_LIMIT")
            return _err("RATE_LIMIT", "Rate limit exceeded.")

    # validate: accept both key ids and (for backwards compatibility with observed usage) server ids
    if not isinstance(id, str) or id.strip() == "":
        _log("error", "VALIDATION_ERROR", detail="validation:id")
        return _err("VALIDATION_ERROR", "Invalid id.", field="id")

    is_key_id = re.match(r"^bq_key_[0-9A-Z]{18,}$", id) is not None
    is_server_id = re.match(r"^bq_srv_[0-9A-Z]{18,}$", id) is not None
    if not (is_key_id or is_server_id):
        _log("error", "VALIDATION_ERROR", detail="validation:id_pattern")
        return _err("VALIDATION_ERROR", "Invalid id format; expected an API key id.", field="id")

    # ambient auth: choose a principal that can manage; schema lacks ACL, so require an active owner/admin to mutate
    users = _load("users.json")
    if not isinstance(users, list):
        users = []
    principal = None
    for u in users:
        if isinstance(u, dict) and u.get("status") == "active" and u.get("role") in ("owner", "admin"):
            principal = u
            break
    if principal is None:
        _log("error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Requires an active user with role owner or admin.")

    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []

    # locate key(s)
    target_indexes = []
    if is_key_id:
        for i, k in enumerate(api_keys):
            if isinstance(k, dict) and k.get("id") == id:
                target_indexes = [i]
                break
        if not target_indexes:
            _log("error", "NOT_FOUND", principal.get("id"))
            return _err("NOT_FOUND", "API key not found.", field="id")
    else:
        # if a server id was provided, revoke all active keys scoped to that server
        for i, k in enumerate(api_keys):
            if isinstance(k, dict) and k.get("server_id") == id and k.get("status") == "active":
                target_indexes.append(i)
        if not target_indexes:
            _log("error", "NOT_FOUND", principal.get("id"))
            return _err("NOT_FOUND", "No active API keys found for the provided server id.", field="id")

    updated = []
    for i in target_indexes:
        k = api_keys[i]
        if not isinstance(k, dict):
            continue
        cur = k.get("status")
        if cur != "active":
            # for single-key revocation, return INVALID_TRANSITION
            if is_key_id:
                _log("error", "INVALID_TRANSITION", principal.get("id"), "transition:not_active")
                return _err("INVALID_TRANSITION", f"API key is not active (current status: {cur}).", from_status=cur, to_status="revoked")
            # for bulk revoke, skip non-active
            continue
        k2 = dict(k)
        k2["status"] = "revoked"
        k2["updated_at"] = now_iso
        api_keys[i] = k2
        updated.append(k2)

    if not updated:
        # no success without effect
        _log("error", "NOT_FOUND", principal.get("id"))
        return _err("NOT_FOUND", "No API keys were revoked.")

    _save("api_keys.json", api_keys)
    _log("ok", None, principal.get("id"))

    if is_key_id:
        return {"api_key": updated[0]}
    return {"api_keys": updated, "revoked_count": len(updated)}
